using System;
using System.Collections.Generic;
using System.IO;
using UnityEditor;
using UnityEditor.Build;
using UnityEditor.Build.Reporting;
using UnityEditor.SceneManagement;
using UnityEngine;

/// <summary>
/// Builds the Android player from the command line.
///
/// Exists so a change can be put on a real phone without opening the editor, and
/// more to the point so the thing that is tested is the thing that was built - a
/// build made by hand between two edits is a build nobody can reproduce.
///
/// It runs the UI builder first. Everything under the Canvas is generated by
/// <see cref="AppUIBuilder"/>, so a player built without that step ships whatever
/// the scene happened to be saved with, which is how a fix reaches a phone and
/// appears not to work.
/// </summary>
public static class BuildApk
{
    const string Scene = "Assets/Scenes/Main.unity";
    const string OutputFolder = "Build";

    /// <summary>
    /// The assets that have to be in the player because nothing references them.
    ///
    /// Opening the project in batch mode rewrites the preloaded list without the
    /// editor pass that fills it in, and what falls out is what no scene points at:
    /// the XR loader settings, and the two shaders that paint the camera feed.
    /// Nothing then fails. The build succeeds, the AR session tracks, the radar
    /// follows the phone - and the camera draws black, because XR Management never
    /// found its Android settings and so never started the ARCore loader. The log
    /// says "No active ARCoreCameraSubsystem is available in this session", four
    /// steps away from the setting that actually went missing.
    ///
    /// Identified by local file id, not by path alone. Both XR settings files hold
    /// one settings object per build target, and the file's main asset is the
    /// wrapper around them - preloading that wrapper looks right in the inspector
    /// and puts nothing usable in the player. These ids are the ones committed in
    /// ProjectSettings.asset; if one ever stops resolving, this fails the build
    /// rather than shipping a black screen.
    /// </summary>
    struct Preload
    {
        public string path;
        public long localId;
        public string what;

        public Preload(string path, long localId, string what)
        {
            this.path = path;
            this.localId = localId;
            this.what = what;
        }
    }

    static readonly Preload[] RequiredPreloads =
    {
        new Preload("Assets/InputSystem_Actions.inputactions", -944628639613478452L,
                    "the input actions"),
        new Preload("Assets/XR/Settings/OpenXR Package Settings.asset", 2495205364760583549L,
                    "OpenXR's Android settings"),
        new Preload("Assets/XR/XRGeneralSettingsPerBuildTarget.asset", 4098870614499507440L,
                    "XR Management's Android settings - the camera feed depends on it"),
        new Preload("Assets/ExtensionsAssets/Runtime/RuntimeConfig.asset", 11400000L,
                    "the ARCore Extensions runtime config"),
    };

    /// <summary>
    /// The camera background shaders, which live in the package cache under a folder
    /// name carrying a hash that changes on every package update. Found by name for
    /// that reason, and by exact name because FindAssets matches on a prefix.
    /// </summary>
    static readonly string[] RequiredShaders =
    {
        "ARCoreBackground",
        "ARCoreBackgroundAfterOpaques",
    };

    /// <summary>
    /// Puts back anything missing from the preloaded list, keeping what is there.
    /// </summary>
    static void RestorePreloadedAssets()
    {
        UnityEngine.Object[] existing = PlayerSettings.GetPreloadedAssets();
        List<UnityEngine.Object> preloaded = new List<UnityEngine.Object>(existing);

        // Nulls are left exactly where they are. A null here does not reliably mean
        // the asset is gone - it can equally mean the asset database has not resolved
        // it yet - and an earlier version of this method tidied them away and saved
        // the result, which deleted the live references to the XR settings and the
        // camera shaders. A stale null costs nothing at runtime. Removing a real one
        // costs the camera feed, silently, until somebody builds and looks.
        int nulls = 0;
        foreach (UnityEngine.Object asset in preloaded)
            if (asset == null) nulls++;

        if (nulls > 0)
            Debug.LogWarning("[Build] " + nulls + " preloaded entr(ies) did not resolve. " +
                             "Left in place - they are not safe to tidy away here.");

        int added = 0;
        bool missing = false;

        foreach (Preload required in RequiredPreloads)
        {
            UnityEngine.Object asset = FindByLocalId(required.path, required.localId);

            if (asset == null)
            {
                Debug.LogError("[Build] Could not find " + required.what + " (" +
                               required.path + ", id " + required.localId + ").");
                missing = true;
                continue;
            }

            if (preloaded.Contains(asset))
                continue;

            preloaded.Add(asset);
            added++;
        }

        foreach (string name in RequiredShaders)
        {
            Shader shader = FindShader(name);

            if (shader == null)
            {
                Debug.LogError("[Build] Missing shader " + name +
                               " - the camera feed will be black.");
                missing = true;
                continue;
            }

            if (preloaded.Contains(shader))
                continue;

            preloaded.Add(shader);
            added++;
        }

        if (missing)
            throw new Exception("Required preloaded assets are missing. See the errors above.");

        if (added == 0)
            return;

        if (preloaded.Count < existing.Length)
            throw new Exception("The preloaded list would shrink from " + existing.Length +
                                " to " + preloaded.Count + ". Refusing to save it.");

        PlayerSettings.SetPreloadedAssets(preloaded.ToArray());
        Debug.Log("[Build] Put back " + added + " preloaded asset(s) that batch mode dropped.");
    }

    /// <summary>
    /// Prints the preloaded list with the local id of each entry, because the whole
    /// failure is a reference collapsing to the wrong object inside the right file -
    /// which every other view of this list renders identically.
    /// </summary>
    static void ReportPreloads(string when)
    {
        UnityEngine.Object[] preloaded = PlayerSettings.GetPreloadedAssets();
        Debug.Log("[Build] Preloaded assets " + when + " - " + preloaded.Length + ":");

        foreach (UnityEngine.Object asset in preloaded)
        {
            if (asset == null)
            {
                Debug.Log("[Build]    (null)");
                continue;
            }

            string guid;
            long id;
            AssetDatabase.TryGetGUIDAndLocalFileIdentifier(asset, out guid, out id);

            Debug.Log("[Build]    " + asset.GetType().Name + " \"" + asset.name +
                      "\"  id=" + id + "  " + AssetDatabase.GetAssetPath(asset));
        }
    }

    /// <summary>
    /// The one object inside an asset file with this local id. Sub-objects cannot be
    /// reached by path, and the wrong one is worse than none - it looks correct.
    /// </summary>
    static UnityEngine.Object FindByLocalId(string path, long localId)
    {
        UnityEngine.Object[] all = AssetDatabase.LoadAllAssetsAtPath(path);

        for (int i = 0; i < all.Length; i++)
        {
            if (all[i] == null)
                continue;

            string guid;
            long id;

            if (!AssetDatabase.TryGetGUIDAndLocalFileIdentifier(all[i], out guid, out id))
                continue;

            if (id == localId)
                return all[i];
        }

        return null;
    }

    static Shader FindShader(string name)
    {
        string[] found = AssetDatabase.FindAssets(name + " t:Shader");

        for (int i = 0; i < found.Length; i++)
        {
            string path = AssetDatabase.GUIDToAssetPath(found[i]);

            if (Path.GetFileNameWithoutExtension(path) == name)
                return AssetDatabase.LoadAssetAtPath<Shader>(path);
        }

        return null;
    }

    [MenuItem("Tools/Build/Android APK")]
    public static void Build()
    {
        BuildTo("ARTrail.apk", bundle: false);
    }

    /// <summary>
    /// The Android App Bundle Google Play takes, from the same scene, signed
    /// with the same upload key. Play re-signs what it hands out with the app
    /// signing key it keeps; this key only proves an upload is ours.
    /// </summary>
    [MenuItem("Tools/Build/Android App Bundle (Play)")]
    public static void BuildBundle()
    {
        BuildTo("ARTrail.aab", bundle: true);
    }

    static void BuildTo(string file, bool bundle)
    {
        string path = Path.Combine(OutputFolder, file);
        Directory.CreateDirectory(OutputFolder);

        bool wasBundle = EditorUserBuildSettings.buildAppBundle;
        EditorUserBuildSettings.buildAppBundle = bundle;

        // The Google key ARCore's Geospatial service needs, from the keys folder
        // and only for the length of the build: ARCore writes it into the
        // manifest from its settings in memory, and the settings file in the
        // repository is saved back without it, whatever happened in between.
        var arcore = Google.XR.ARCoreExtensions.Internal.ARCoreExtensionsProjectSettings.Instance;
        arcore.AndroidAuthenticationStrategySetting =
            Google.XR.ARCoreExtensions.Internal.AndroidAuthenticationStrategy.ApiKey;
        arcore.AndroidCloudServicesApiKey = ArcoreKey();

        try
        {
            BuildPlayer(path);
        }
        finally
        {
            EditorUserBuildSettings.buildAppBundle = wasBundle;
            arcore.AndroidCloudServicesApiKey = string.Empty;
            arcore.Save();
        }
    }

    /// <summary>
    /// The ARCore API key, from keys\arcore-api-key.txt in the user's folder.
    ///
    /// Refuses to build without one, or with one Google says does not exist:
    /// the key in the project was deleted in Google Cloud in September, every
    /// build after that shipped a camera that could never place a marker, and
    /// the app only said "Cannot calibrate here". Offline, it warns and builds.
    /// </summary>
    static string ArcoreKey()
    {
        string file = Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.UserProfile),
                                   "keys", "arcore-api-key.txt");

        string key = File.Exists(file) ? File.ReadAllText(file).Trim() : string.Empty;

        if (!key.StartsWith("AIza") || key.Length != 39)
            throw new BuildFailedException("No ARCore API key in " + file +
                                           " (one line, starting AIza). Without it the camera cannot place markers.");

        // Any call on the ARCore API checks the key, and the discovery document
        // needs nothing else. A key restricted to the app is "403 blocked" here,
        // without the app's certificate, and that is the expected answer; only a
        // key Google does not know at all is "400 not valid".
        try
        {
            using (var http = new System.Net.Http.HttpClient { Timeout = TimeSpan.FromSeconds(10) })
            {
                int status = (int)http.GetAsync(
                    "https://arcore.googleapis.com/$discovery/rest?version=v1&key=" + key).Result.StatusCode;

                if (status == 400)
                    throw new BuildFailedException("Google says the ARCore API key in " + file +
                                                   " is not valid (deleted or mistyped). Make a new one in Google Cloud.");
            }
        }
        catch (BuildFailedException)
        {
            throw;
        }
        catch (Exception exception)
        {
            Debug.LogWarning("[Build] Could not check the ARCore key with Google (" +
                             exception.GetBaseException().Message + "). Building anyway.");
        }

        return key;
    }

    /// <summary>
    /// Refuses a scene whose ARCore session would start with Geospatial off.
    ///
    /// On 21 September the ARCore sample folder was deleted, and with it the
    /// config asset the scene's ARCore Extensions pointed at. Every build after
    /// that ran ARCore's defaults - Geospatial disabled - and placed no marker,
    /// while the builder only noted "No ARCoreExtensionsConfig linked".
    /// </summary>
    static void RequireGeospatial()
    {
        var extensions = UnityEngine.Object.FindFirstObjectByType<Google.XR.ARCoreExtensions.ARCoreExtensions>(
            FindObjectsInactive.Include);
        var config = extensions != null ? extensions.ARCoreExtensionsConfig : null;

        if (config == null || config.GeospatialMode != Google.XR.ARCoreExtensions.GeospatialMode.Enabled)
            throw new BuildFailedException(
                "The scene's ARCore Extensions has " + (config == null ? "no config" : "Geospatial off in " + config.name) +
                ". Assets/Settings/ARTrailGeospatialConfig.asset is the one it should use.");
    }

    static void BuildPlayer(string path)
    {

        // The scene on disk is generated output. Rebuilding it here is what keeps
        // "it compiles" and "it is in the player" from being different claims.
        EditorSceneManager.OpenScene(Scene, OpenSceneMode.Single);
        AppUIBuilder.BuildForPreview();
        EditorSceneManager.SaveOpenScenes();

        RequireGeospatial();

        AppIcons.Apply();

        ReportPreloads("as batch mode left it");
        RestorePreloadedAssets();
        ReportPreloads("as the build will use it");

        // glTFast's shaders, which nothing else references, for creators' models.
        ModelShaders.Make();

        // Signing, with the password kept out of everything that gets committed.
        //
        // Unity's -keystorePass and -keyaliasPass command line arguments are
        // ignored here: the first release build ran to the end of the post
        // processor and stopped at "Unable to sign the application; please
        // provide passwords!". So the password arrives through the environment
        // and is set for this run only.
        //
        // The keystore's path and its alias live in ProjectSettings, which is
        // right - neither is secret. The password must never end up there. If
        // this is ever changed, check ProjectSettings.asset before committing.
        //
        // And if a keystore is configured but no password was given, this stops
        // rather than quietly handing back a debug-signed APK that looks like a
        // release one. A build that is not signed by the right key is worse than
        // no build, because it installs and runs and cannot be updated later.
        string keyPass = Environment.GetEnvironmentVariable("ARTRAIL_KEYSTORE_PASS");

        if (!string.IsNullOrEmpty(keyPass))
        {
            PlayerSettings.Android.useCustomKeystore = true;
            PlayerSettings.Android.keystorePass = keyPass;
            PlayerSettings.Android.keyaliasPass = keyPass;

            Debug.Log("[Build] Signing with " + PlayerSettings.Android.keystoreName +
                      " as \"" + PlayerSettings.Android.keyaliasName + "\"");
        }
        else if (PlayerSettings.Android.useCustomKeystore)
        {
            throw new Exception(
                "A keystore is configured but ARTRAIL_KEYSTORE_PASS is not set, so the " +
                "APK could only be debug-signed. Set it for this build and run again.");
        }

        BuildPlayerOptions options = new BuildPlayerOptions
        {
            scenes = new[] { Scene },
            locationPathName = path,
            target = BuildTarget.Android,
            targetGroup = BuildTargetGroup.Android,
            options = BuildOptions.None
        };

        BuildReport report = BuildPipeline.BuildPlayer(options);
        BuildSummary summary = report.summary;

        if (summary.result == BuildResult.Succeeded)
        {
            Debug.Log("[Build] " + path + "  " +
                      (summary.totalSize / (1024 * 1024)) + " MB  in " +
                      Math.Round(summary.totalTime.TotalSeconds) + "s");
            return;
        }

        Debug.LogError("[Build] Failed: " + summary.result + ", " +
                       summary.totalErrors + " error(s)");

        // Batch mode reports success on exit code alone unless something fails the
        // process, so a failed build has to say so loudly enough to stop a script.
        EditorApplication.Exit(1);
    }
}
